-- Disposable database only. The Phase 1 access suite rolls its fixture back.
begin;
create schema tests;
create table tests.context(key text primary key,value text);
grant usage on schema tests to anon,authenticated;
grant all on tests.context to anon,authenticated;
create function tests.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end; $$;
create function tests.rejects(command text,label text) returns void language plpgsql as $$ declare rejected boolean:=false; begin begin execute command; exception when others then rejected:=true; end; if not rejected then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end; $$;
grant execute on all functions in schema tests to anon,authenticated;
insert into auth.users values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into tests.context values('trip',public.create_trip('{"name":"Assistant test","description":"","minimum_participants":2,"options":[{"destination":"Goa","start_date":"2027-01-01","end_date":"2027-01-03","estimated_cost":12000}],"invitees":["Maya"]}')::text);
insert into tests.context select 'option',id::text from public.trip_options;
insert into tests.context select 'token',invitation_token from public.trips;
insert into tests.context select 'version',public.get_leader_context((select value::uuid from tests.context where key='trip'))->>'version';
select tests.assert(length((select value from tests.context where key='version'))=64,'assistant context has a stable version hash');
select tests.assert(public.get_leader_context((select value::uuid from tests.context where key='trip'))->>'version'=(select value from tests.context where key='version'),'context version is reproducible without mutations');
select tests.assert(not(public.get_leader_context((select value::uuid from tests.context where key='trip'))::text like '%invitation_token%'),'assistant context excludes invitation secrets');
select tests.assert(public.get_trip_decision((select value::uuid from tests.context where key='trip')) is null,'no saved decision is an explicit empty result');
select tests.rejects(format('select public.approve_trip_decision(%L,%L,%L,false)',(select value from tests.context where key='trip'),(select value from tests.context where key='option'),(select value from tests.context where key='version')),'approval must be explicit');
select tests.rejects(format('select public.approve_trip_decision(%L,%L,%L,true)',(select value from tests.context where key='trip'),'00000000-0000-4000-8000-000000000001',(select value from tests.context where key='version')),'unknown option cannot be selected');
select tests.rejects(format('select public.approve_trip_decision(%L,%L,%L,true)',(select value from tests.context where key='trip'),(select value from tests.context where key='option'),repeat('0',64)),'stale preview cannot be approved');
select public.approve_trip_decision((select value::uuid from tests.context where key='trip'),(select value::uuid from tests.context where key='option'),(select value from tests.context where key='version'),true) is not null as saved;
select tests.assert((select count(*)=1 from public.trip_decisions),'one approved brief snapshot is persisted');
select tests.assert((select approved_by=auth.uid() from public.trip_decisions),'approver identity is derived server-side');
select tests.assert((select (brief_snapshot->'options'->0->>'estimated_cost')::numeric=12000 from public.trip_decisions),'brief snapshot uses actual saved option cost');
select tests.rejects('update public.trip_decisions set brief_snapshot=''{}''','leader cannot forge a stored brief directly');
select tests.rejects('delete from public.trip_decisions','leader cannot erase snapshot outside approved RPC');
select tests.rejects('select * from public.assistant_usage','quota table is not client-readable');
-- A real anonymous response changes the context but must not rewrite an approved snapshot.
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select tests.rejects(format('select public.get_leader_context(%L)',(select value from tests.context where key='trip')),'anonymous caller cannot get leader context');
select tests.rejects(format('select public.get_trip_decision(%L)',(select value from tests.context where key='trip')),'anonymous caller cannot read saved decision');
select tests.rejects('select * from public.trip_decisions','anonymous caller cannot read brief table');
select tests.rejects(format('select public.approve_trip_decision(%L,%L,%L,true)',(select value from tests.context where key='trip'),(select value from tests.context where key='option'),(select value from tests.context where key='version')),'anonymous caller cannot approve');
select tests.rejects(format('select public.reserve_assistant_call(%L)',(select value from tests.context where key='trip')),'anonymous caller cannot reserve AI usage');
insert into tests.context values('edit',public.submit_response((select value from tests.context where key='token'),jsonb_build_object('name','Maya','available_option_ids',jsonb_build_array((select value from tests.context where key='option')),'max_budget',10000,'preferred_destinations',jsonb_build_array('Goa'),'interests',jsonb_build_array('Food'),'commitment','Interested')));
select tests.assert(not(public.get_invitation((select value from tests.context where key='token')) ? 'brief_snapshot'),'public invitation does not disclose brief snapshot');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select tests.assert(public.get_leader_context((select value::uuid from tests.context where key='trip'))->>'version'<>(select value from tests.context where key='version'),'new response changes context version');
select tests.assert((select jsonb_array_length(brief_snapshot->'responses')=0 from public.trip_decisions),'later responses do not mutate approved brief');
select tests.assert(jsonb_array_length(public.get_trip_decision((select value::uuid from tests.context where key='trip'))->'brief_snapshot'->'responses')=0,'saved brief can be reloaded from persisted snapshot');
select tests.rejects(format('select public.approve_trip_decision(%L,%L,%L,true)',(select value from tests.context where key='trip'),(select value from tests.context where key='option'),(select value from tests.context where key='version')),'approval rejects a now-stale preview');
select public.approve_trip_decision((select value::uuid from tests.context where key='trip'),(select value::uuid from tests.context where key='option'),public.get_leader_context((select value::uuid from tests.context where key='trip'))->>'version',true) is not null as updated;
select tests.assert((select jsonb_array_length(brief_snapshot->'responses')=1 from public.trip_decisions),'explicit reapproval captures the new authoritative snapshot');
select public.reserve_assistant_call((select value::uuid from tests.context where key='trip')) from generate_series(1,6);
select tests.rejects(format('select public.reserve_assistant_call(%L)',(select value from tests.context where key='trip')),'seventh AI request in one minute is rejected');
reset role;
update public.assistant_usage set minute=minute-interval '1 minute', daily_calls=100 where owner_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select tests.rejects(format('select public.reserve_assistant_call(%L)',(select value from tests.context where key='trip')),'daily AI request ceiling is enforced after minute window changes');
reset role;
update public.assistant_usage set day=day-1,minute=minute-interval '1 day' where owner_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select public.reserve_assistant_call((select value::uuid from tests.context where key='trip'));
reset role;
select tests.assert((select daily_calls=1 and minute_calls=1 from public.assistant_usage),'quota resets on a new UTC day and minute');
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select tests.assert((select count(*)=0 from public.trip_decisions),'other leader cannot read brief rows');
select tests.rejects(format('select public.get_leader_context(%L)',(select value from tests.context where key='trip')),'other leader cannot get context');
select tests.rejects(format('select public.get_trip_decision(%L)',(select value from tests.context where key='trip')),'other leader cannot get decision');
select tests.rejects(format('select public.approve_trip_decision(%L,%L,%L,true)',(select value from tests.context where key='trip'),(select value from tests.context where key='option'),(select value from tests.context where key='version')),'other leader cannot approve decision');
select tests.rejects(format('select public.reserve_assistant_call(%L)',(select value from tests.context where key='trip')),'other leader cannot spend trip AI quota');
reset role;
rollback;
